    local function hasFileSystemSupport()
        local hasWritefile = pcall(function() return type(writefile) == "function" end)
        local hasReadfile = pcall(function() return type(readfile) == "function" end)
        local hasIsfile = pcall(function() return type(isfile) == "function" end)
        return hasWritefile and hasReadfile and hasIsfile
    end
    
    local fileSystemSupported = hasFileSystemSupport()
    
    local function saveVerifiedKey(key)
        if not fileSystemSupported then return false end
        local ok = pcall(function()
            writefile("verified_key.txt", key)
        end)
        return ok
    end
    
    local function loadVerifiedKey()
        if not fileSystemSupported then 
            return nil 
        end
        
        local ok, content = pcall(function()
            return readfile("verified_key.txt")
        end)
        
        if not ok or not content then 
            return nil 
        end
        return content
    end
    
    local function clearSavedKey()
        if not fileSystemSupported then return false end
        local ok = pcall(function() delfile("verified_key.txt") end)
        return ok
    end
    
    local function loadUIFactory()
        return function(Colors, Players, TweenService, UserInputService, Lighting)
            local function Create(class, props, children)
            local obj = Instance.new(class)
            for prop, val in pairs(props) do
                obj[prop] = val
            end
            if children then
                for _, child in ipairs(children) do
                    child.Parent = obj
                end
            end
            return obj
        end

        local function AddShimmer(button, color)
            local shimmer = Create("Frame", {
                Name = "Shimmer",
                Size = UDim2.new(0, 40, 1, 0),
                Position = UDim2.new(-0.2, 0, 0, 0),
                BackgroundColor3 = color or Color3.fromRGB(255, 255, 255),
                BackgroundTransparency = 0.8,
                BorderSizePixel = 0,
                ZIndex = button.ZIndex + 1,
                Parent = button
            }, {
                Create("UIGradient", {
                    Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 1),
                        NumberSequenceKeypoint.new(0.5, 0),
                        NumberSequenceKeypoint.new(1, 1)
                    }),
                    Rotation = 15
                })
            })

            task.spawn(function()
                while button and button.Parent do
                    shimmer.Position = UDim2.new(-0.2, 0, 0, 0)
                    local t = TweenService:Create(shimmer, TweenInfo.new(1.5, Enum.EasingStyle.Quart, Enum.EasingDirection.InOut), {
                        Position = UDim2.new(1.2, 0, 0, 0)
                    })
                    t:Play()
                    t.Completed:Wait()
                    task.wait(3)
                end
            end)
        end
        
